import type {
  ResourcesSections,
  SectionsShown,
  ViewContext,
  SectionName,
  PermissionsState,
} from './types/integration-permission-selector'
import {ListView} from '@github-ui/list-view'

import {PermissionHeader} from './components/PermissionHeader'
import {PermissionSelectorBar} from './components/PermissionSelectorBar'

import {useCallback, useEffect, useState, useRef} from 'react'

import {HiddenPermissionInputs} from './components/HiddenPermissionInputs'
import {PermissionRow} from './components/PermissionRow'
import {PermissionBlankSlate} from './components/PermissionBlankSlate'

const SMALL_VIEWPORT_THRESHOLD = 480
const XSMALL_VIEWPORT_THRESHOLD = 455

export interface IntegrationPermissionSelectorProps {
  resources: ResourcesSections
  view: ViewContext
  showSections: SectionsShown
  appMode: 'edit' | 'create' | null
}

const RepoInstallTarget = {
  INSTALL_TARGET_ALL: 'install_target_all',
  INSTALL_TARGET_SELECTED: 'install_target_selected',
  INSTALL_TARGET_NONE: 'install_target_none',
} as const

type RepoInstallTarget = (typeof RepoInstallTarget)[keyof typeof RepoInstallTarget]

export function IntegrationPermissionSelector(props: IntegrationPermissionSelectorProps) {
  const [sections, setSectionShown] = useState<SectionsShown>(props.showSections)

  const [permissionsSelected, setPermissionsSelected] = useState<PermissionsState>(
    props.view.grantedPermissions || {
      repository: {},
      business: {},
      user: {},
      organization: {},
    },
  )

  useEffect(() => {
    if (props.view.grantedPermissions) {
      const showRepoSection = Object.keys(props.view.grantedPermissions.repository).length !== 0

      if (showRepoSection) {
        // eslint-disable-next-line react-hooks/set-state-in-effect
        setSectionShown(prev => ({
          ...prev,
          repository: true,
        }))
      }
    }
  }, [props])

  const clearSelected = useCallback((type: SectionName) => {
    setPermissionsSelected(prev => ({
      ...prev,
      [type]: {},
    }))
  }, [])

  const [metadataRequired, setMetadataRequired] = useState<boolean>(false)

  useEffect(() => {
    const repoPermissionsSelected = Object.keys(permissionsSelected.repository)
    const hasNonMetadata = repoPermissionsSelected.some(item => item !== 'Metadata')

    // eslint-disable-next-line react-hooks/set-state-in-effect
    setMetadataRequired(hasNonMetadata)

    if (hasNonMetadata && !repoPermissionsSelected.includes('Metadata')) {
      setPermissionsSelected(prev => ({
        ...prev,
        repository: {
          ...prev.repository,
          Metadata: 'Read-only',
        },
      }))
    }
  }, [permissionsSelected.repository])

  const toggleRepoPermissionVisibility = useCallback(
    (id: string) => {
      setSectionShown(prev => ({
        ...prev,
        repository: id !== RepoInstallTarget.INSTALL_TARGET_NONE,
      }))
      if (id === RepoInstallTarget.INSTALL_TARGET_NONE) {
        clearSelected('repository')
      }
    },
    [setSectionShown, clearSelected],
  )

  useEffect(() => {
    const radioButtons = document.querySelectorAll('input[type="radio"].js-installation-repositories-radio')

    function handleRadioChange(event: Event) {
      const target = event.target as HTMLInputElement
      const id = target.id

      toggleRepoPermissionVisibility(id)
    }

    for (const radio of radioButtons) {
      radio.addEventListener('change', handleRadioChange)
    }

    return () => {
      for (const radio of radioButtons) {
        radio.removeEventListener('change', handleRadioChange)
      }
    }
  }, [toggleRepoPermissionVisibility])

  const didRun = useRef(false)

  useEffect(() => {
    if (didRun.current) return
    didRun.current = true

    const repoPermissions = Object.keys(permissionsSelected.repository)
    const hasRepoPerms = repoPermissions.length > 0

    if (hasRepoPerms) {
      const allRadio = document.querySelector<HTMLInputElement>(
        'input[type="radio"].js-installation-repositories-radio[value="all"]',
      )
      const selectedRadio = document.querySelector<HTMLInputElement>(
        'input[type="radio"].js-installation-repositories-radio[value="selected"]',
      )
      // Only default to "all" if neither "all" nor "selected" is already checked.
      // This preserves the existing selection when editing a token with select repositories.
      if (allRadio && !allRadio.checked && !(selectedRadio && selectedRadio.checked)) {
        allRadio.checked = true
        allRadio.dispatchEvent(new Event('change', {bubbles: true}))
      }
    }
  }, [permissionsSelected.repository])

  const findSectionSelected = useCallback((): SectionName | undefined => {
    if (sections.repository) {
      return 'repository'
    }
    const otherSection = Object.entries(sections).find(([key, value]) => key !== 'repository' && value)
    if (otherSection) {
      return otherSection[0] as SectionName
    }
  }, [sections])
  const [sectionSelected, setSectionSelected] = useState<SectionName>('repository')

  useEffect(() => {
    const currentSection = findSectionSelected()
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setSectionSelected(currentSection ?? 'repository')
  }, [sections, findSectionSelected])

  const handleRemove = useCallback(
    (permissionTitle: string) => {
      setPermissionsSelected(prev => {
        const updatedSection = {...prev[sectionSelected]}
        delete updatedSection[permissionTitle]
        return {
          ...prev,
          [sectionSelected]: updatedSection,
        }
      })
    },
    [sectionSelected],
  )

  const handleSelectAction = useCallback(
    (text: string, action: string) => {
      setPermissionsSelected(prev => ({
        ...prev,
        [sectionSelected]: {
          ...prev[sectionSelected],
          [text]: action,
        },
      }))
    },
    [sectionSelected],
  )

  const listViewRef = useRef<HTMLDivElement>(null)
  const [listViewSize, setListViewSize] = useState<'xs' | 'sm' | 'lg'>('lg')

  // Observe the list element directly (not the viewport) and read its width from
  // the ResizeObserver entry rather than getBoundingClientRect, so resizes never
  // force a synchronous layout. Coalesce into a frame and bail when the discrete
  // size band is unchanged to avoid redundant re-renders.
  useEffect(() => {
    const element = listViewRef.current
    if (!element) return

    const computeSize = (width: number): 'xs' | 'sm' | 'lg' => {
      if (width <= XSMALL_VIEWPORT_THRESHOLD) return 'xs'
      if (width <= SMALL_VIEWPORT_THRESHOLD) return 'sm'
      return 'lg'
    }

    let frame = 0
    const observer = new ResizeObserver(([entry]) => {
      if (!entry) return
      cancelAnimationFrame(frame)
      frame = requestAnimationFrame(() => {
        const borderBox = entry.borderBoxSize?.[0]
        const width = borderBox ? borderBox.inlineSize : entry.contentRect.width
        const next = computeSize(width)
        setListViewSize(prev => (prev === next ? prev : next))
      })
    })
    observer.observe(element)
    return () => {
      cancelAnimationFrame(frame)
      observer.disconnect()
    }
  }, [])

  return (
    <>
      <HiddenPermissionInputs
        resources={props.resources}
        showSections={props.showSections}
        permissionsSelected={permissionsSelected}
      />
      <PermissionHeader appMode={props.appMode} />
      <div ref={listViewRef}>
        <ListView
          metadata={
            <PermissionSelectorBar
              sections={sections}
              permissionsSelected={permissionsSelected}
              setPermissionsSelected={setPermissionsSelected}
              tabSelected={sectionSelected}
              tabOnClick={setSectionSelected}
              resources={props.resources}
              requireMetadata={metadataRequired}
              listViewSize={listViewSize}
            />
          }
          title="Permissions"
          className="border border-2 rounded-2 tmp-mb-3"
          itemsListStyle={{minHeight: '250px', maxHeight: '400px', overflowY: 'auto'}}
        >
          {(() => {
            const selectedKeys = Object.keys(permissionsSelected[sectionSelected])
            const hasSelected = selectedKeys.length > 0

            return hasSelected ? (
              selectedKeys.sort().map(text => {
                const fullPermission = props.resources[sectionSelected]?.find(p => p.metadata.title === text)
                return (
                  fullPermission && (
                    <PermissionRow
                      key={text}
                      title={text}
                      actions={fullPermission.metadata.fgp}
                      selected={permissionsSelected[sectionSelected]?.[text]}
                      onSelect={action => handleSelectAction(text, action)}
                      description={fullPermission.metadata.description}
                      docsUrl={fullPermission.metadata.docs_url}
                      onRemove={() => handleRemove(text)}
                      requireMetadata={metadataRequired}
                      listViewSize={listViewSize}
                    />
                  )
                )
              })
            ) : (
              <PermissionBlankSlate section={sectionSelected} />
            )
          })()}
        </ListView>
      </div>
    </>
  )
}
